import unittest
from candidate import unique

class TestUnique(unittest.TestCase):
    def test_normal_int_list(self):
        result = unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
        self.assertEqual(result, [0, 2, 3, 5, 9, 123])
        self.assertEqual(len(result), len(set(result)))

    def test_normal_float_list(self):
        result = unique([3.14, 2.71, 3.14, 1.41])
        self.assertEqual(result, [1.41, 2.71, 3.14])

    def test_empty_list(self):
        self.assertEqual(unique([]), [])

    def test_single_element(self):
        self.assertEqual(unique([42]), [42])

    def test_duplicates_only(self):
        self.assertEqual(unique([7, 7, 7]), [7])

    def test_none_in_list(self):
        result = unique([None, None])
        self.assertEqual(result, [None])

    def test_none_as_input(self):
        with self.assertRaises(TypeError):
            unique(None)

    def test_unhashable_element(self):
        with self.assertRaises(TypeError):
            unique([[1], [2]])

    def test_generator_input(self):
        result = unique(i for i in [4, 1, 4, 2])
        self.assertEqual(result, [1, 2, 4])

    def test_tuple_input(self):
        result = unique((9, 5, 9, 1))
        self.assertEqual(result, [1, 5, 9])

    def test_boolean_values(self):
        result = unique([True, False, True])
        self.assertEqual(result, [False, True])

    def test_large_numbers(self):
        large = [10**9, -10**9, 10**9]
        result = unique(large)
        self.assertEqual(result, [-10**9, 10**9])

    def test_negative_numbers(self):
        result = unique([-3, -1, -2, -1])
        self.assertEqual(result, [-3, -2, -1])

    def test_mixed_numerics(self):
        result = unique([1, 2.5, 0, 2.5, 1])
        self.assertEqual(result, [0, 1, 2.5])

    def test_homogeneous_tuple_elements(self):
        result = unique([(1, 2), (3, 4), (1, 2)])
        self.assertEqual(result, [(1, 2), (3, 4)])

    def test_incomparable_types_sorting_raises(self):
        with self.assertRaises(TypeError):
            unique([1, 'a', 2])

    def test_string_input(self):
        result = unique('cba')
        self.assertEqual(result, ['a', 'b', 'c'])

    def test_non_list_iterable(self):
        result = unique({1, 3, 2})
        self.assertEqual(result, [1, 2, 3])

if __name__ == '__main__':
    unittest.main()
